SELECT device_code, DATE_TRUNC('DAY', reading_ts) AS activity_day, MIN(reading_ts) AS first_reading_ts, STDDEV_SAMP(status_bits) AS status_bits_stddev, ROUND(SUM(humidity) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS humidity_per_dv_04, COUNT(*) AS event_count, PERCENTILE_APPROX(pressure, ARRAY(0.25, 0.5, 0.75)) AS pressure_quartiles, STDDEV_SAMP(humidity) AS humidity_stddev FROM device_readings GROUP BY ROLLUP (device_code, DATE_TRUNC('DAY', reading_ts)) HAVING humidity_stddev < 0 ORDER BY humidity_stddev
